package upsertqueries_test

import (
	"errors"
	"testing"

	"foundry.test/consumer/internal/queryfixture"
	"foundry.test/consumer/models"
	"foundry.test/consumer/upsertqueries"
	"github.com/weiloon1234/Foundry-Go/database"
	"github.com/weiloon1234/Foundry-Go/database/query"
	"github.com/weiloon1234/Foundry-Go/decimal"
)

type conflictLookup struct{}

func TestPostgresConflictCalculationsDefaultsAndTriggers(t *testing.T) {
	queryfixture.Run(t, func(tx *database.Tx, _ []models.User) error {
		for _, sql := range []string{
			`CREATE TABLE write_records (code bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT true,note text,amount numeric NOT NULL DEFAULT 1.25)`,
		} {
			if _, err := tx.Exec(t.Context(), sql); err != nil {
				return err
			}
		}
		q, f := models.QueryWriteRecords(), models.WriteRecordFields()
		initial, err := q.Create(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter").SetNote("kept").SetAmount(conflictDecimal(t, "1000000000000000000.1")))
		if err != nil {
			return err
		}
		for _, sql := range []string{
			`CREATE FUNCTION adjust_proposed_amount() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.amount := NEW.amount + 0.5; RETURN NEW; END $$`,
			`CREATE TRIGGER adjust_proposed_amount BEFORE INSERT ON write_records FOR EACH ROW EXECUTE FUNCTION adjust_proposed_amount()`,
		} {
			if _, err := tx.Exec(t.Context(), sql); err != nil {
				return err
			}
		}
		rows := q.ConflictRows()
		stored := models.WriteRecordFieldsAt(rows.Stored())
		proposed := models.WriteRecordFieldsAt(rows.Proposed())
		policy := query.OnConflict(f.Name).DoUpdate(
			query.SetConflictValue(f.Amount, query.Add(stored.Amount, proposed.Amount)),
			query.SetConflictValue(f.Note, query.CoalesceNullable(proposed.Note, stored.Note)),
		).Where(f.Enabled.Eq(true)).WhereRows(proposed.Enabled.Eq(true))
		result, err := q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter").SetAmount(conflictDecimal(t, "0.2")), policy)
		if err != nil {
			return err
		}
		actual, ok := result.Get()
		note, hasNote := actual.Note.Get()
		if !ok || actual.Code != initial.Code || actual.Amount.String() != "1000000000000000000.8" || !hasNote || note != "kept" {
			t.Fatal("calculation lost exact value, proposed trigger changes or nullable fallback", actual.Amount.String())
		}
		skipped, err := q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter").SetEnabled(false), policy)
		if err != nil || skipped.IsSet() {
			t.Fatal("proposed condition did not skip update", err)
		}
		many, err := q.UpsertMany(t.Context(), tx, []models.WriteRecordDraft{
			models.WriteRecordDraft{}.SetName("counter"), models.WriteRecordDraft{}.SetName("new"),
		}, policy)
		if err != nil {
			return err
		}
		amounts := map[string]string{}
		for _, item := range many {
			amounts[item.Name] = item.Amount.String()
		}
		if len(many) != 2 || amounts["counter"] != "1000000000000000002.55" || amounts["new"] != "1.75" {
			t.Fatal(amounts)
		}
		cleared, err := q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter").ClearNote(),
			query.OnConflict(f.Name).DoUpdate(query.SetConflictValue(f.Note, proposed.Note)))
		if err != nil {
			return err
		}
		clearedRecord, present := cleared.Get()
		if !present || !clearedRecord.Note.IsNull() {
			t.Fatal("nullable expression did not clear value")
		}
		return nil
	})
}

func TestPostgresConflictScalarAndCorrelatedAssignments(t *testing.T) {
	queryfixture.Run(t, func(tx *database.Tx, _ []models.User) error {
		if _, err := tx.Exec(t.Context(), `CREATE TABLE write_records (code bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT true,note text,amount numeric NOT NULL DEFAULT 1.25)`); err != nil {
			return err
		}
		q, f := models.QueryWriteRecords(), models.WriteRecordFields()
		if _, err := q.CreateMany(t.Context(), tx, []models.WriteRecordDraft{
			models.WriteRecordDraft{}.SetName("counter"),
			models.WriteRecordDraft{}.SetName("reference").SetAmount(conflictDecimal(t, "91.125")),
		}); err != nil {
			return err
		}
		rows := q.ConflictRows()
		proposed := models.WriteRecordFieldsAt(rows.Proposed())
		lookup := query.As[conflictLookup](query.CTE("foundry_upsert", q.Where(f.Name.Eq("reference"))), "lookup")
		link := query.Correlate(rows, lookup)
		outer := models.WriteRecordFieldsAt(query.OuterScope(link, rows.Stored()))
		inner := models.WriteRecordFieldsAt(query.InnerScope(link, lookup.Scope()))
		selected := query.SelectCorrelatedValue(link, inner.Amount.Value()).Where(query.Greater(inner.Amount, outer.Amount)).Limit(1)
		policy := query.OnConflict(f.Name).DoUpdate(query.SetConflictValue(f.Amount, query.Coalesce(query.CorrelatedScalarRowQuery(selected), proposed.Amount)))
		result, err := q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter"), policy)
		if err != nil {
			return err
		}
		actual, ok := result.Get()
		if !ok || actual.Amount.String() != "91.125" {
			t.Fatal("correlated assignment lost outer scope or CTE", actual.Amount.String())
		}
		// With no matching lookup, the nullable scalar falls back to the proposed value.
		result, err = q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter").SetAmount(conflictDecimal(t, "2.5")), policy)
		if err != nil {
			return err
		}
		actual, ok = result.Get()
		if !ok || actual.Amount.String() != "2.5" {
			t.Fatal("empty scalar did not use proposed fallback")
		}

		// A scalar with multiple results must preserve the database error and roll back.
		allLink := query.Correlate(rows, q)
		allFields := models.WriteRecordFieldsAt(query.InnerScope(allLink, q.Scope()))
		multiple := query.SelectCorrelatedValue(allLink, allFields.Amount.Value())
		invalid := query.OnConflict(f.Name).DoUpdate(query.SetConflictValue(f.Amount, query.Coalesce(query.CorrelatedScalarRowQuery(multiple), proposed.Amount)))
		_, err = q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter"), invalid)
		var dbErr *database.Error
		if !errors.As(err, &dbErr) || dbErr.SQLState() != "21000" {
			t.Fatal("scalar cardinality was hidden", err)
		}
		current, err := q.Where(f.Name.Eq("counter")).First(t.Context(), tx)
		if err != nil {
			return err
		}
		kept, present := current.Get()
		if !present || kept.Amount.String() != "2.5" {
			t.Fatal("failed calculation persisted")
		}
		independent := query.ConflictScalarRowQuery(rows, query.SelectValue(q.Where(f.Name.Eq("reference")), f.Amount.Value()))
		nullable := query.ConflictScalarNullableRowQuery(rows, query.SelectValue(q.Where(f.Name.Eq("reference")), f.Note.Value()))
		result, err = q.Upsert(t.Context(), tx, models.WriteRecordDraft{}.SetName("counter"),
			query.OnConflict(f.Name).DoUpdate(query.SetConflictValue(f.Amount, query.Coalesce(independent, proposed.Amount)), query.SetConflictValue(f.Note, nullable)))
		if err != nil {
			return err
		}
		actual, ok = result.Get()
		if !ok || actual.Amount.String() != "91.125" || !actual.Note.IsNull() {
			t.Fatal("independent scalars lost type or nullable value")
		}
		return nil
	})
}

func TestPostgresConflictCalculationOnExcludedTable(t *testing.T) {
	queryfixture.Run(t, func(tx *database.Tx, _ []models.User) error {
		if _, err := tx.Exec(t.Context(), `CREATE TABLE excluded (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL DEFAULT 'before')`); err != nil {
			return err
		}
		q, f := upsertqueries.QueryExcluded(), upsertqueries.ExcludedRecordFields()
		original, err := q.Create(t.Context(), tx, upsertqueries.ExcludedRecordDraft{}.SetName("before"))
		if err != nil {
			return err
		}
		rows := q.ConflictRows()
		stored := upsertqueries.ExcludedRecordFieldsAt(rows.Stored())
		proposed := upsertqueries.ExcludedRecordFieldsAt(rows.Proposed())
		policy := query.OnConflict(f.ID).DoUpdate(query.SetConflictValue(f.Name, query.Concat(stored.Name, proposed.Name))).
			WhereRows(query.NotEqual(stored.Name, proposed.Name))
		result, err := q.Upsert(t.Context(), tx, upsertqueries.ExcludedRecordDraft{}.SetID(original.ID).SetName("after"), policy)
		if err != nil {
			return err
		}
		actual, ok := result.Get()
		if !ok || actual.Name != "beforeafter" {
			t.Fatal("stored and proposed excluded rows confused")
		}
		return nil
	})
}

func conflictDecimal(t *testing.T, text string) decimal.Decimal {
	t.Helper()
	v, err := decimal.Parse(text)
	if err != nil {
		t.Fatal(err)
	}
	return v
}
